CREATE TABLE daily (d TEXT, v INTEGER);
INSERT INTO daily VALUES ('d1', 10), ('d2', 20), ('d3', 30), ('d4', 40), ('d5', 50);

SELECT d, v,
       SUM(v) OVER (ORDER BY d ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS rolling2,
       SUM(v) OVER (ORDER BY d ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running
FROM daily;

CREATE TABLE daily (d TEXT, v INTEGER);
INSERT INTO daily VALUES ('d1', 10), ('d2', 20), ('d3', 30), ('d4', 40), ('d5', 50);

SELECT d, v,
       LAG(v) OVER (ORDER BY d) AS prev_v,
       v - LAG(v) OVER (ORDER BY d) AS diff,
       LEAD(v) OVER (ORDER BY d) AS next_v
FROM daily;

